#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_N 1000000L          /* maximum allowed n */
#define MAX_K 1000000000L       /* maximum allowed k */

int main(int argc, char *argv[])
{
    /* Expect exactly two numeric arguments (program name + 2 args) */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    errno = 0;
    long k = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Validate ranges */
    if (n <= 0 || k <= 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > MAX_N || k > MAX_K) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Josephus computation (0‑based) */
    long survivor = 0; // result for i = 1
    for (long i = 2; i <= n; ++i) {
        survivor = (survivor + k) % i;
    }
    printf("%ld\n", survivor + 1);
    return 0;
}
